H=Path(__file__).resolve().parents[1];read=lambda p:json.loads(p.read_text());a=read(H/'results/analysis.json');v=read(H/'results/oracle-all-points.json');con=read(H/'results/contrasts.json');source=read(H/'results/source-conditioned-divertor.json')
