for c in con:
 lines.append(f"| {c['from']} → {c['to']} | {c['delta_outputs']['stellarator_09__stellaris__lcoe_calc__lcoe']:.6f} | {'; '.join(x['source_local_identity']+': '+x['from']+' → '+x['to'] for x in c['predicate_changes']) or 'none'} |")
